import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";
import type { AgentAnnouncerController } from "./hooks/use-agent-announcer";

export type AgentAnnouncerProps = Omit<
  ComponentProps<"span">,
  "children" | "role"
> & {
  announcer: AgentAnnouncerController;
};

/** The conversation's one status region. Render it once, outside the scrolling log. */
export function AgentAnnouncer({
  announcer,
  className,
  ...props
}: AgentAnnouncerProps): ReactElement {
  return (
    <span
      aria-atomic="true"
      aria-live="polite"
      data-slot="agent-announcer"
      role="status"
      className={cn("sr-only", className)}
      {...props}
    >
      {announcer.message}
    </span>
  );
}

"use client";

import { ArrowDownIcon } from "lucide-react";
import {
  type ComponentProps,
  type ReactElement,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import { ScrollArea } from "@/registry/default/ui/scroll-area";
import {
  AGENT_SCROLL_OFFSET_VAR,
  getAgentScrollOffset,
  isAgentScrollAtBottom,
} from "./lib/agent-scroll";

export type AgentConversationProps = ComponentProps<"div"> & {
  contentClassName?: string;
  /** Names the jump-to-latest button, which shows only when this is set. */
  scrollToLatestLabel?: string;
};

export function AgentConversation({
  children,
  className,
  contentClassName,
  scrollToLatestLabel,
  ...props
}: AgentConversationProps): ReactElement {
  const rootRef = useRef<HTMLDivElement>(null);
  const isAtBottomRef = useRef(true);
  const hasScrolledToInitialContentRef = useRef(false);
  const [isAtBottom, setIsAtBottom] = useState(true);

  const getViewport = useCallback(
    (): HTMLElement | null =>
      rootRef.current?.querySelector('[data-slot="scroll-area-viewport"]') ??
      null,
    [],
  );

  const recordScroll = useCallback((viewport: HTMLElement): void => {
    viewport.style.setProperty(
      AGENT_SCROLL_OFFSET_VAR,
      getAgentScrollOffset(viewport.scrollTop),
    );
    const next = isAgentScrollAtBottom(viewport);
    isAtBottomRef.current = next;
    setIsAtBottom(next);
  }, []);

  const scrollToLatest = useCallback((): void => {
    const viewport = getViewport();
    if (!viewport) return;
    viewport.scrollTo({ top: viewport.scrollHeight });
    recordScroll(viewport);
  }, [getViewport, recordScroll]);

  useEffect(() => {
    const viewport = getViewport();
    if (!viewport) return;
    const onScroll = (): void => recordScroll(viewport);
    viewport.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    return () => viewport.removeEventListener("scroll", onScroll);
  }, [getViewport, recordScroll]);

  // Follow content that grows without a re-render, such as streamed text or images loading.
  useEffect(() => {
    const content = rootRef.current?.querySelector(
      '[data-slot="scroll-area-content"]',
    );
    if (!content) return;
    const observer = new ResizeObserver(() => {
      if (isAtBottomRef.current) scrollToLatest();
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, [scrollToLatest]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: New children mean new content to follow; land the first scroll before paint.
  useLayoutEffect(() => {
    if (!hasScrolledToInitialContentRef.current || isAtBottomRef.current) {
      scrollToLatest();
      hasScrolledToInitialContentRef.current = true;
    }
  }, [children, scrollToLatest]);

  return (
    <div
      ref={rootRef}
      data-slot="agent-conversation"
      className={cn("relative h-full min-h-0", className)}
      {...props}
    >
      <ScrollArea className="h-full" overscrollContain scrollFade>
        <div
          className={cn(
            // Inside a popover crossfade snapshot ([data-previous]), keep the reader's place.
            // The variable is AGENT_SCROLL_OFFSET_VAR; Tailwind needs it spelled out here.
            "flex min-h-full in-data-previous:-translate-y-(--agent-conversation-scroll-top) flex-col gap-8",
            contentClassName,
          )}
        >
          {children}
        </div>
      </ScrollArea>
      {scrollToLatestLabel && !isAtBottom && (
        <div className="pointer-events-none absolute inset-x-0 bottom-4 flex justify-end px-4">
          <Button
            aria-label={scrollToLatestLabel}
            className="pointer-events-auto rounded-full before:rounded-full"
            data-slot="agent-conversation-scroll-button"
            onClick={scrollToLatest}
            size="icon-sm"
            variant="outline"
          >
            <ArrowDownIcon aria-hidden="true" />
          </Button>
        </div>
      )}
    </div>
  );
}

"use client";

import type { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import { CheckIcon, CopyIcon, PencilIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useCopyToClipboard } from "@/registry/default/hooks/use-copy-to-clipboard";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import { Toolbar, ToolbarButton } from "@/registry/default/ui/toolbar";
import {
  Tooltip,
  TooltipPopup,
  TooltipProvider,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";

export type AgentMessageActionsProps = Omit<
  ToolbarPrimitive.Root.Props,
  "aria-label"
> & {
  label: string;
};

export function AgentMessageActions({
  label,
  className,
  ...props
}: AgentMessageActionsProps): ReactElement {
  return (
    <TooltipProvider>
      <Toolbar
        aria-label={label}
        data-slot="agent-message-actions"
        className={cn(
          "w-fit items-center gap-0.5 rounded-none border-0 bg-transparent p-0",
          className,
        )}
        {...props}
      />
    </TooltipProvider>
  );
}

export type AgentMessageActionProps = Omit<
  ButtonProps,
  "aria-label" | "children" | "size" | "variant"
> & {
  label: string;
  children: ReactNode;
  /** Tooltip content. Defaults to `label`. */
  tooltip?: ReactNode;
};

export function AgentMessageAction({
  label,
  children,
  tooltip = label,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentMessageActionProps): ReactElement {
  // An action that can't do anything is a real disabled button, never aria-disabled alone.
  const inactive = disabled || (!onClick && !render);
  return (
    <Tooltip disableHoverablePopup>
      <TooltipTrigger
        render={
          <ToolbarButton
            disabled={inactive}
            focusableWhenDisabled={false}
            render={
              <Button
                aria-label={label}
                className={cn(
                  "text-muted-foreground hover:text-foreground",
                  className,
                )}
                data-slot="agent-message-action"
                disabled={inactive}
                onClick={onClick}
                render={render}
                size="icon-xs"
                variant="ghost"
                {...props}
              />
            }
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipPopup side="bottom">{tooltip}</TooltipPopup>
    </Tooltip>
  );
}

export type AgentMessageCopyActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render" | "tooltip"
> & {
  text: string;
  copiedLabel: string;
  /** Called after the text reaches the clipboard. Announce `copiedLabel` here; the button's name stays `label`. */
  onCopy?: () => void;
};

export function AgentMessageCopyAction({
  text,
  label,
  copiedLabel,
  onCopy,
  disabled,
  ...props
}: AgentMessageCopyActionProps): ReactElement {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ onCopy });
  return (
    <AgentMessageAction
      data-copied={isCopied || undefined}
      disabled={disabled || !text}
      label={label}
      tooltip={isCopied ? copiedLabel : label}
      onClick={() => copyToClipboard(text)}
      {...props}
    >
      {isCopied ? (
        <CheckIcon aria-hidden="true" />
      ) : (
        <CopyIcon aria-hidden="true" />
      )}
    </AgentMessageAction>
  );
}

export type AgentMessageEditActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render"
> & {
  onEdit: () => void;
};

export function AgentMessageEditAction({
  onEdit,
  ...props
}: AgentMessageEditActionProps): ReactElement {
  return (
    <AgentMessageAction onClick={onEdit} {...props}>
      <PencilIcon aria-hidden="true" />
    </AgentMessageAction>
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import type { ComponentProps, ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";

export type AgentMessageProps = useRender.ComponentProps<"div"> & {
  from: "user" | "assistant";
  actions?: ReactNode;
  /** Keep actions shown and in the flow, such as on the latest finished reply. */
  actionsAlwaysVisible?: boolean;
};

export function AgentMessage({
  from,
  actions,
  actionsAlwaysVisible = false,
  children,
  className,
  render,
  ...props
}: AgentMessageProps): ReactElement {
  const user = from === "user";
  const defaultProps = {
    children: (
      <>
        <div
          data-slot="agent-message-content"
          className={cn(
            "flex min-w-0 max-w-3xl flex-col gap-2 text-foreground text-sm leading-6 [overflow-wrap:anywhere]",
            user &&
              "ms-auto w-fit max-w-[min(85%,48rem)] rounded-lg bg-muted px-3 py-2",
          )}
        >
          {children}
        </div>
        {actions != null && (
          <div
            data-slot="agent-message-actions-slot"
            className={cn(
              "z-10 flex pt-1 transition-opacity motion-reduce:transition-none",
              actionsAlwaysVisible
                ? "static"
                : "absolute top-full in-[[data-slot=agent-message]:focus-within]:opacity-100 in-[[data-slot=agent-message]:hover]:opacity-100 opacity-0 pointer-coarse:opacity-100 has-data-popup-open:opacity-100",
              user ? "end-0 self-end" : "start-0 self-start",
            )}
          >
            {actions}
          </div>
        )}
      </>
    ),
    className: cn(
      "flex w-full min-w-0 flex-col gap-1",
      actions != null && "relative",
      className,
    ),
    "data-actions-visible": actionsAlwaysVisible || undefined,
    "data-from": from,
    "data-slot": "agent-message",
  };

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
  });
}

/** Wraps prompt and reply prose. Plain text keeps its line breaks; block markup wraps normally. */
export function AgentMessageText({
  className,
  ...props
}: ComponentProps<"div">): ReactElement {
  return (
    <div
      data-slot="agent-message-text"
      className={cn(
        "min-w-0 whitespace-pre-wrap [overflow-wrap:anywhere] has-[ol,ul,p,pre,h1,h2,h3,h4,h5,h6,blockquote,table,hr]:whitespace-normal",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type AgentAnnouncementState,
  type AgentPhase,
  getAgentAnnouncement,
  getAgentAnnouncerMessage,
} from "../lib/get-agent-announcement";

export type AgentAnnouncerLabels = Partial<
  Record<Exclude<AgentPhase, "idle">, string>
>;

export type AgentAnnouncerOptions = {
  phase: AgentPhase;
  /** Localized text for each phase. A phase without a label is never announced. */
  labels: AgentAnnouncerLabels;
  /** Replaces the phase label, such as the error or the approval question. */
  detail?: string;
  /** Changing it starts a new baseline, so a switched conversation isn't replayed. */
  conversationId?: string;
};

export function useAgentAnnouncer({
  phase,
  labels,
  detail,
  conversationId,
}: AgentAnnouncerOptions) {
  const [message, setMessage] = useState("");
  const previousRef = useRef<AgentAnnouncementState | null>(null);
  const text = phase === "idle" ? "" : (detail ?? labels[phase] ?? "");

  useEffect(() => {
    const next = { conversationId, phase, text };
    const announcement = getAgentAnnouncement(previousRef.current, next);
    previousRef.current = next;
    if (announcement)
      setMessage((current) => getAgentAnnouncerMessage(current, announcement));
  }, [conversationId, phase, text]);

  /** Announce a one-off result, such as a copied message. */
  const announce = useCallback((value: string): void => {
    if (value)
      setMessage((current) => getAgentAnnouncerMessage(current, value));
  }, []);

  return { announce, message };
}

export type AgentAnnouncerController = ReturnType<typeof useAgentAnnouncer>;

"use client";

import { useMediaQuery } from "@/registry/default/hooks/use-media-query";

/**
 * The agent family's reduced-motion check for motion timed in JavaScript, such as an
 * exit delay or an animation loop. CSS transitions use `motion-reduce:` variants instead.
 */
export function useAgentReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

export type AgentPhase =
  | "idle"
  | "thinking"
  | "working"
  | "approval"
  | "done"
  | "stopped"
  | "failed";

export type AgentAnnouncementState = {
  phase: AgentPhase;
  /** What this phase would say: a phase label, or a detail such as the error. */
  text: string;
  conversationId?: string;
};

function isBusy(phase: AgentPhase): boolean {
  return phase === "thinking" || phase === "working";
}

export function getAgentAnnouncement(
  previous: AgentAnnouncementState | null,
  next: AgentAnnouncementState,
): string {
  // A new mount or conversation only records a baseline; its state isn't replayed.
  if (previous === null || previous.conversationId !== next.conversationId)
    return "";
  if (next.phase !== previous.phase) {
    if (isBusy(next.phase) && isBusy(previous.phase)) return "";
    return next.text;
  }
  // Busy text is progress, streamed or not: only settled phases re-announce new text.
  if (isBusy(next.phase) || next.text === previous.text) return "";
  return next.text;
}

const REPEAT_MARK = " ";

/** Live regions skip unchanged content, so a repeat toggles a trailing no-break space. */
export function getAgentAnnouncerMessage(
  current: string,
  text: string,
): string {
  if (current === text) return `${text}${REPEAT_MARK}`;
  return text;
}

export const AGENT_SCROLL_OFFSET_VAR = "--agent-conversation-scroll-top";

/**
 * Base UI popover viewports crossfade a cloned snapshot of the outgoing content,
 * and a clone keeps attributes but not scroll position. Written to the viewport's
 * inline style, this offset travels with the clone so the transcript can be
 * translated back to where the reader was.
 */
export function getAgentScrollOffset(scrollTop: number): string {
  return `${Math.max(0, scrollTop)}px`;
}

export type AgentScrollMetrics = {
  scrollHeight: number;
  scrollTop: number;
  clientHeight: number;
};

const BOTTOM_THRESHOLD_PX = 24;

export function isAgentScrollAtBottom({
  scrollHeight,
  scrollTop,
  clientHeight,
}: AgentScrollMetrics): boolean {
  return scrollHeight - scrollTop - clientHeight <= BOTTOM_THRESHOLD_PX;
}
